package dev.smokekitchen.cooking;

import dev.smokekitchen.content.ContentCatalog;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class WetCookingTest {
    private DishRecipe recipe(String id){if(ContentCatalog.DISHES.isEmpty())ContentCatalog.load();return ContentCatalog.DISHES.stream().filter(r->r.id().equals(id)).findFirst().orElseThrow();}
    private CookingBatch batch(CookingBatch.Method method){var b=new CookingBatch();b.method=method;b.addWater(6);b.temperature=100;b.salt=1;b.soy=1;b.vinegar=1;return b;}
    private void ready(CookingBatch b){b.ingredients.forEach(p->{p.cooked=1;p.coveredCookingSeconds=20;});}
    @Test void addingWaterCoolsWithoutCreatingWaterPastCapacity(){var b=new CookingBatch();b.temperature=200;assertEquals(6,b.addWater(6));assertTrue(b.temperature<50);double before=b.temperature;assertEquals(0,b.addWater(6));assertEquals(6,b.water);assertEquals(before,b.temperature);}
    @Test void waterBuffersColdIngredientsAndNeverExceedsBoilingTemperature(){var b=batch(CookingBatch.Method.BOIL);b.add("shrimp",CookingBatch.Cut.WHOLE,1.6,false,false);assertTrue(b.temperature>98);for(int i=0;i<20;i++)b.tick(3,false);assertEquals(100,b.temperature);}
    @Test void steamNeedsBothWaterAndLid(){var b=batch(CookingBatch.Method.STEAM);b.add("fish",CookingBatch.Cut.WHOLE,1.6,false,false);for(int i=0;i<160;i++)b.tick(2,false);assertEquals(0,b.ingredients.getFirst().cooked);for(int i=0;i<160;i++)b.tick(2,true);assertTrue(b.ready());assertTrue(b.ingredients.getFirst().coveredCookingSeconds>=15);}
    @Test void aDryHotPotCharsInsteadOfMagicallyCookingOrRecovering(){var b=new CookingBatch();b.method=CookingBatch.Method.STEW;b.add("chicken",CookingBatch.Cut.WHOLE,1.6,false,false);for(int i=0;i<180;i++)b.tick(3,true);assertFalse(b.ready());assertTrue(b.burnt());b.addWater(6);assertTrue(b.burnt());}
    @Test void displayedTemperatureMatchesPreparationBoundary(){var r=recipe("fried_rice");var b=new CookingBatch();b.oil=1;b.temperature=109.5;b.add("egg",CookingBatch.Cut.WHOLE,1,false,false);assertNotEquals("preheat",r.problem(b).orElseThrow().key());b.ingredients.getFirst().temperatureOnAdd=109.49;assertEquals("preheat",r.problem(b).orElseThrow().key());}
    @Test void shrimpRequiresGingerAndActuallyBoilingWaterAtAddition(){var r=recipe("boiled_shrimp");var b=batch(CookingBatch.Method.BOIL);b.add("ginger",CookingBatch.Cut.SLICE,1,false,false);b.temperature=100;for(int i=0;i<3;i++)b.add("shrimp",CookingBatch.Cut.WHOLE,1.6,false,false);ready(b);assertTrue(r.matches(b));b.ingredients.get(1).temperatureOnAdd=50;assertEquals("boiling",r.problem(b).orElseThrow().key());b.ingredients.get(1).temperatureOnAdd=100;b.ingredients.get(1).waterOnAdd=0;assertEquals("boiling",r.problem(b).orElseThrow().key());}
    @Test void steamedFishRequiresPreparedHerbsCoveredCookingAndFinishingSoy(){var r=recipe("steamed_fish");var b=batch(CookingBatch.Method.STEAM);b.add("fish",CookingBatch.Cut.WHOLE,1.6,false,false);b.add("fish",CookingBatch.Cut.WHOLE,1.6,false,false);b.add("ginger",CookingBatch.Cut.SLICE,1,false,false);b.add("scallion",CookingBatch.Cut.DICE,1,false,false);ready(b);assertEquals("finish",r.problem(b).orElseThrow().key());b.season("soy");assertTrue(r.matches(b));b.ingredients.getFirst().coveredCookingSeconds=0;assertEquals("cover",r.problem(b).orElseThrow().key());}
    @Test void crabNeedsSlicedGingerWaterAndCoveredHeat(){var r=recipe("steamed_crab");var b=batch(CookingBatch.Method.STEAM);b.add("crab",CookingBatch.Cut.WHOLE,1.6,false,false);b.add("crab",CookingBatch.Cut.WHOLE,1.6,false,false);b.add("ginger",CookingBatch.Cut.SLICE,1,false,false);ready(b);assertTrue(r.matches(b));b.water=0;assertEquals("water",r.problem(b).orElseThrow().key());b.water=6;b.ingredients.getLast().cut=CookingBatch.Cut.WHOLE;assertEquals("cut",r.problem(b).orElseThrow().key());}
    @Test void mushroomSoupRequiresPieces(){var r=recipe("mushroom_soup");var b=batch(CookingBatch.Method.BOIL);for(int i=0;i<3;i++)b.add("mushroom",CookingBatch.Cut.SLICE,1,false,false);ready(b);assertTrue(r.matches(b));b.ingredients.getFirst().cut=CookingBatch.Cut.WHOLE;assertEquals("cut",r.problem(b).orElseThrow().key());}
    @Test void eggSoupRequiresTomatoCookedBeforeEgg(){var r=recipe("tomato_egg_soup");var b=batch(CookingBatch.Method.BOIL);b.add("tomato",CookingBatch.Cut.DICE,1,false,false);b.add("tomato",CookingBatch.Cut.DICE,1,false,false);ready(b);b.add("egg",CookingBatch.Cut.WHOLE,1,false,false);ready(b);assertTrue(r.matches(b));b.ingredients.getLast().priorCooked.put("tomato",.1);assertEquals("stage",r.problem(b).orElseThrow().key());}
    @Test void carrotAndBeefStewsRequireMeatFirstAndCoveredCooking(){for(String id:new String[]{"carrot_meat_stew","beef_potato_stew"}){var r=recipe(id);var b=batch(CookingBatch.Method.STEW);String meat=id.startsWith("carrot")?"pork":"beef",veg=id.startsWith("carrot")?"carrot":"potato";b.add(meat,CookingBatch.Cut.DICE,1.6,false,false);b.add(meat,CookingBatch.Cut.DICE,1.6,false,false);ready(b);b.add(veg,CookingBatch.Cut.DICE,1,false,false);b.add(veg,CookingBatch.Cut.DICE,1,false,false);b.add(id.startsWith("carrot")?"ginger":"onion",id.startsWith("carrot")?CookingBatch.Cut.SLICE:CookingBatch.Cut.DICE,1,false,false);ready(b);assertTrue(r.matches(b));b.ingredients.get(2).priorCooked.put(meat,.1);assertEquals("stage",r.problem(b).orElseThrow().key());}}
    @Test void milkGoesIntoSoftDicedPumpkin(){var r=recipe("pumpkin_soup");var b=batch(CookingBatch.Method.BOIL);b.add("pumpkin",CookingBatch.Cut.DICE,1,false,false);b.add("pumpkin",CookingBatch.Cut.DICE,1,false,false);ready(b);b.add("milk",CookingBatch.Cut.WHOLE,1,false,true);ready(b);assertTrue(r.matches(b));b.ingredients.getLast().priorCooked.put("pumpkin",.3);assertEquals("stage",r.problem(b).orElseThrow().key());}
}
